// MOCK camera source. Produces synthetic camera frames (schema from SCHEMA_VERSION) so the dashboard can be
// built before perception exists. These values are generated by sine waves, not
// measured from a face. The UI must label them as mock via `kind: 'mock'`.
//
// Interface shared by every data source: { kind, subscribe(listener) => unsubscribe }.
// A real source (for example a WebSocket) implements the same interface.

import { BLENDSHAPE_NAMES, SCHEMA_VERSION, poseMatrixFromAngles } from '../contracts/cameraFrame.js'

export const MOCK_CYCLE_MS = 10000
const TRACKING_UNTIL_MS = 7000
const PARTIAL_UNTIL_MS = 8500

const round = (v, places = 3) => Math.round(v * 10 ** places) / 10 ** places
const wave = (t, periodMs, phase = 0) => (Math.sin((2 * Math.PI * t) / periodMs + phase) + 1) / 2

function mockFeatures(t, names) {
  const out = {}
  names.forEach((name, i) => {
    // Most shapes stay low; a few rise and fall so the panel has something to show.
    const amplitude = i % 7 === 0 ? 0.9 : 0.15
    out[name] = round(amplitude * wave(t, 2000 + i * 137, i))
  })
  return out
}

// Pure function: elapsed time in the loop → one camera frame.
export function buildMockFrame(elapsedMs, timestampMs) {
  const t = ((elapsedMs % MOCK_CYCLE_MS) + MOCK_CYCLE_MS) % MOCK_CYCLE_MS
  const base = { schema_version: SCHEMA_VERSION, timestamp_ms: timestampMs }

  if (t < TRACKING_UNTIL_MS) {
    const angles = {
      yaw_deg: round(30 * Math.sin((2 * Math.PI * t) / 6000), 2),
      pitch_deg: round(15 * Math.sin((2 * Math.PI * t) / 4500), 2),
      roll_deg: round(10 * Math.sin((2 * Math.PI * t) / 5200), 2),
    }
    return {
      ...base,
      tracking_state: 'tracking',
      features: mockFeatures(t, BLENDSHAPE_NAMES),
      head_pose: { matrix: poseMatrixFromAngles(angles), ...angles },
      confidence: null,
    }
  }
  if (t < PARTIAL_UNTIL_MS) {
    return {
      ...base,
      tracking_state: 'partial',
      features: mockFeatures(t, BLENDSHAPE_NAMES.slice(1, 20)),
      head_pose: null,
      confidence: null,
    }
  }
  return { ...base, tracking_state: 'lost', features: {}, head_pose: null, confidence: null }
}

export function createMockCameraSource({ intervalMs = 100, now = () => Date.now() } = {}) {
  const listeners = new Set()
  let timer = null
  let startedAt = 0

  const tick = () => {
    const ts = now()
    const frame = buildMockFrame(ts - startedAt, ts)
    listeners.forEach((listener) => listener(frame))
  }

  return {
    kind: 'mock',
    subscribe(listener) {
      listeners.add(listener)
      if (timer === null) {
        startedAt = now()
        timer = setInterval(tick, intervalMs)
      }
      return () => {
        listeners.delete(listener)
        if (listeners.size === 0) {
          clearInterval(timer)
          timer = null
        }
      }
    },
  }
}
